from typing import List

def parse_music(music_string: str) -> List[int]:
    note_to_beats = {
        'o': 4,
        'o|': 2,
        '.|': 1
    }

    notes = music_string.split()
    result = []

    for note in notes:
        if note in note_to_beats:
            result.append(note_to_beats[note])

    return result

